scoped_refptr<VideoFrame> CloneVideoFrameWithLayout(const VideoFrame* src_frame, const VideoFrameLayout& dst_layout) {
    if (!src_frame->IsMappable() || src_frame->format() != dst_layout.GetFormat()) {
        LOG(ERROR) << "Source frame not mappable or format mismatch.";
        return nullptr;
    }

    scoped_refptr<VideoFrame> dst_frame = VideoFrame::CreateFrame(dst_layout, src_frame->timestamp(), base::TimeDelta(), base::TimeDelta());
    if (!dst_frame) {
        LOG(ERROR) << "Failed to create destination VideoFrame.";
        return nullptr;
    }

    for (size_t i = 0; i < src_frame->NumPlanes(); ++i) {
        const uint8_t* src_data = src_frame->data(i);
        uint8_t* dst_data = dst_frame->mutable_data(i);
        size_t size = src_frame->rows(i) * src_frame->stride(i);
        memcpy(dst_data, src_data, size);
    }

    return dst_frame;
}

scoped_refptr<VideoFrame> CloneVideoFrameWithLayout(const VideoFrame* src_frame, const VideoFrameLayout& dst_layout) {
    if (!src_frame->IsMappable() || src_frame->layout().format() != dst_layout.format()) {
        LOG(ERROR) << "Source frame is not mappable or format does not match destination layout.";
        return nullptr;
    }

    scoped_refptr<VideoFrame> dst_frame = VideoFrame::Create(dst_layout, src_frame->timestamp(), base::TimeDelta());
    if (!dst_frame) {
        LOG(ERROR) << "Failed to create destination VideoFrame.";
        return nullptr;
    }

    for (size_t i = 0; i < src_frame->layout().planes().size(); ++i) {
        const VideoFrameLayout::PlaneInfo& src_plane = src_frame->layout().planes()[i];
        const VideoFrameLayout::PlaneInfo& dst_plane = dst_layout.planes()[i];
        if (src_plane.stride == dst_plane.stride) {
            memcpy(dst_frame->data(i), src_frame->data(i), src_plane.stride * src_frame->height());
        } else {
            for (size_t y = 0; y < src_frame->height(); ++y) {
                memcpy(dst_frame->data(i) + y * dst_plane.stride,
                       src_frame->data(i) + y * src_plane.stride,
                       std::min(src_plane.stride, dst_plane.stride));
            }
        }
    }

    return dst_frame;
}

